# Append content to the Talus doc
req2 = urllib.request.Request(
    f'https://open.feishu.cn/open-apis/docx/v1/documents/{doc_token}/blocks/{doc_token}/children',
    data=json.dumps({
        'children': [{
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': 'Talus 知识库首页 · 2026-05-27'}
                }]
            }
        }, {
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': '今晚淬火Session核心产出：'}
                }]
            }
        }, {
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': '1. 六条元规则四条矛盾解决原则（时间优先/显性优先/可逆性优先/最小化优先）'}
                }]
            }
        }, {
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': '2. shigraph三层混合架构（链上/链下/预言机）物理落点确认'}
                }]
            }
        }, {
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': '3. 合约草稿EchoShigraphAntiSpam.sol审查反馈（4条）'}
                }]
            }
        }, {
            'block_type': 2,
            'text': {
                'elements': [{
                    'text_run': {'content': '待办：向听风申请完整写权限，同步淬火成果至此目录'}
                }]
            }
